rating":null,"parameter_format":"POSITIONAL","components":[{"type":"HEADER","format":"TEXT","text":"Installation complete"},{"type":"BODY","text":"Hi {{1}}, your {{2}} installation is complete! Our technician has configured your connection, and you're now ready to go online. If you have any issues, feel free to reply or contact {{3}} for assistance.","example":{"body_text":[["John","Fibre Broadband","support@telco.com"]]}}],"rejection_reason":null,"metadata":{"source":"waba_message_templates"}}]$tmpls$::jsonb) as x(
    meta_waba_id text,meta_template_id text,name text,category text,language text,status text,
    quality_rating text,parameter_format text,components jsonb,rejection_reason text,metadata jsonb
  )
)
insert into public.templates(
  organization_id,waba_id,meta_template_id,name,category,language,status,quality_rating,
  parameter_format,components,rejection_reason,metadata,last_synced_at
)
select o.id,w.id,p.meta_template_id,p.name,p.category,p.language,p.status,p.quality_rating,
       p.parameter_format,coalesce(p.components,'[]'::jsonb),p.rejection_reason,p.metadata,now()
from payload p
cross join public.organizations o
join public.wabas w on w.organization_id=o.id and w.meta_waba_id=p.meta_waba_id
where o.slug='alazab-group'
on conflict (waba_id,name,language) do update
set meta_template_id=excluded.meta_template_id,category=excluded.category,status=excluded.status,
    quality_rating=excluded.quality_rating,parameter_format=excluded.parameter_format,
    components=excluded.components,rejection_reason=excluded.rejection_reason,
    metadata=public.templates.metadata || excluded.metadata,last_synced_at=excluded.last_synced_at,
    updated_at=now();

