insert into public.whatsapp_flows(
  organization_id,waba_id,meta_flow_id,name,status,categories,validation_errors,json_version,
  data_api_version,endpoint_uri,preview_url,metadata,last_synced_at
)
select o.id,w.id,p.meta_flow_id,p.name,p.status,
       coalesce(array(select jsonb_array_elements_text(coalesce(p.categories,'[]'::jsonb))),array[]::text[]),
       coalesce(p.validation_errors,'[]'::jsonb),p.json_version,p.data_api_version,
       p.endpoint_uri,p.preview_url,p.metadata,now()
from payload p
cross join public.organizations o
join public.wabas w on w.organization_id=o.id and w.meta_waba_id=p.meta_waba_id
where o.slug='alazab-group'
on conflict (waba_id,meta_flow_id) do update
set name=excluded.name,status=excluded.status,categories=excluded.categories,
    validation_errors=excluded.validation_errors,json_version=excluded.json_version,
    data_api_version=excluded.data_api_version,endpoint_uri=excluded.endpoint_uri,
    preview_url=excluded.preview_url,metadata=public.whatsapp_flows.metadata || excluded.metadata,
    last_synced_at=excluded.last_synced_at,updated_at=now();

