insert into public.waba_subscribed_apps(
  organization_id,waba_id,meta_app_id,local_meta_app_id,app_name,app_link,app_namespace,
  app_category,override_callback_uri,is_azwa,status,raw,last_synced_at
)
select o.id,w.id,p.meta_app_id,a.id,p.app_name,p.app_link,p.app_namespace,p.app_category,
       p.override_callback_uri,(p.meta_app_id='1061494059972503'),'active',p.raw,now()
from payload p
cross join public.organizations o
join public.wabas w on w.organization_id=o.id and w.meta_waba_id=p.meta_waba_id
left join public.meta_apps a on a.organization_id=o.id and a.meta_app_id=p.meta_app_id
where o.slug='alazab-group'
on conflict (waba_id,meta_app_id) do update
set local_meta_app_id=excluded.local_meta_app_id,app_name=excluded.app_name,
    app_link=excluded.app_link,app_namespace=excluded.app_namespace,
    app_category=excluded.app_category,override_callback_uri=excluded.override_callback_uri,
    is_azwa=excluded.is_azwa,status='active',raw=excluded.raw,
    last_synced_at=excluded.last_synced_at,updated_at=now();

insert into public.meta_app_wabas(organization_id,meta_app_id,waba_id,status)
select s.organization_id,s.local_meta_app_id,s.waba_id,'active'
from public.waba_subscribed_apps s
where s.organization_id=(select id from public.organizations where slug='alazab-group')
  and s.local_meta_app_id is not null
on conflict (meta_app_id,waba_id) do update set status='active',updated_at=now();

insert into public.meta_app_wabas(organization_id,meta_app_id,waba_id,status)
select o.id,a.id,w.id,
       case when exists (
         select 1 from public.waba_subscribed_apps s
         where s.waba_id=w.id and s.meta_app_id='1061494059972503'
       ) then 'active' else 'pending' end
from public.organizations o
join public.meta_apps a on a.organization_id=o.id and a.meta_app_id='1061494059972503'
join public.wabas w on w.organization_id=o.id
where o.slug='alazab-group'
on conflict (meta_app_id,waba_id) do update set status=excluded.status,updated_at=now();

insert into public.webhook_endpoints(
  organization_id,meta_app_id,endpoint_type,url,status,verification_status,metadata
)
select o.id,a.id,'meta_whatsapp',
       'https://wa.alazab.com/webhooks/meta/whatsapp',
       'active','pending_credentials',
       jsonb_build_object('source','new_azwa_backend','central',true)
from public.organizations o
join public.meta_apps a on a.organization_id=o.id and a.meta_app_id='1061494059972503'
where o.slug='alazab-group'
on conflict (organization_id,meta_app_id,endpoint_type,url) do update
set status='active',metadata=public.webhook_endpoints.metadata || excluded.metadata,updated_at=now();

