select
  (select count(*) from public.business_portfolios where meta_business_id='314437023701205') as portfolios,
  (select count(*) from public.meta_apps where organization_id=(select id from public.organizations where slug='alazab-group')) as apps,
  (select count(*) from public.wabas where organization_id=(select id from public.organizations where slug='alazab-group')) as wabas,
  (select count(*) from public.whatsapp_numbers where organization_id=(select id from public.organizations where slug='alazab-group')) as numbers,
  (select count(*) from public.templates where organization_id=(select id from public.organizations where slug='alazab-group')) as templates,
  (select count(*) from public.whatsapp_flows where organization_id=(select id from public.organizations where slug='alazab-group')) as flows,
  (select count(*) from public.waba_subscribed_apps where organization_id=(select id from public.organizations where slug='alazab-group')) as observed_subscriptions;
